```python
def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        cols = [c for c, v in enumerate(row) if v != 8]
        if not cols:
            continue
        # fill gaps within contiguous segments of pattern cells
        for i in range(len(cols) - 1):
            a, b = cols[i], cols[i + 1]
            if b - a > 1:
                for c in range(a + 1, b):
                    out[r][c] = 2
    return out
